package mage.player.ai;
import mage.Mana;import mage.abilities.*;import mage.cards.Card;import mage.constants.*;import mage.game.permanent.Permanent;import mage.game.stack.StackObject;import java.util.*;
import static mage.player.ai.FourthSeatRealGameTest.check;import static mage.player.ai.RecoveryChecks.*;
public final class FourthSeatRecoveredProtocolTest {
 static class Chain {
  final FourthSeatRealGameTest.Fixture f=new FourthSeatRealGameTest.Fixture();final Permanent kodama,packleader,baloths;final int initial;
  Chain()throws Exception{this("g.GarruksPackleader","Garruk's Packleader");}
  Chain(String drawClass,String drawName)throws Exception{f.game.initializeRollbackOrder();kodama=f.board("k.KodamaOfTheEastTree","Kodama of the East Tree");packleader=f.board(drawClass,drawName);baloths=f.board("r.RampagingBaloths","Rampaging Baloths");library(f,30);for(int i=0;i<12;i++)f.hand("basiclands.Forest","Forest");initial=f.bot.getLibrary().size();Card land=f.hand("basiclands.Forest","Forest");check(f.bot.playLand(land,f.game,false),"Initial chain land failed");f.game.checkStateAndTriggered();check(!f.game.getStack().isEmpty(),"Real chain absent");}
  void progress(){for(int i=0;i<40&&f.bot.getLibrary().size()>initial-2;i++)resolve(f);check(f.bot.getLibrary().size()<initial&&!f.game.getStack().isEmpty(),"No finite draw progress with pending chain");}
  boolean prompt(){return f.bot.chooseUse(Outcome.Detriment,"Draw game because of infinite looping?",null,f.game);}
  Ability source(UUID id){for(StackObject o:f.game.getStack())if(id.equals(o.getSourceId()))return o.getStackAbility();throw new AssertionError("Expected pending source");}
 }
 public static void main(String[]args)throws Exception{
  run("Natural finite chain survives real detector and drains",()->{final int[] refusals={0};org.apache.log4j.Logger log=org.apache.log4j.Logger.getLogger(ComputerPlayerFourthSeat.class);log.setLevel(org.apache.log4j.Level.DEBUG);org.apache.log4j.AppenderSkeleton capture=new org.apache.log4j.AppenderSkeleton(){protected void append(org.apache.log4j.spi.LoggingEvent e){if(String.valueOf(e.getRenderedMessage()).contains("BOUNDED_FINITE_PROGRESS_REFUSAL"))refusals[0]++;}public void close(){}public boolean requiresLayout(){return false;}};log.addAppender(capture);try{Chain c=new Chain();int steps=0;while(!c.f.game.getStack().isEmpty()&&steps++<200){resolve(c.f);check(!c.f.game.hasEnded(),"Finite chain became engine draw");}check(c.f.game.getStack().isEmpty(),"Finite chain failed bounded drain");check(c.f.bot.getLibrary().size()<c.initial,"No actual draws");check(refusals[0]==1,"Real engine detector did not exercise exactly one bounded refusal");}finally{log.removeAppender(capture);}});
  for(String[] engine:new String[][]{{"g.GarruksUprising","Garruk's Uprising"},{"o.OutcasterTrailblazer","Outcaster Trailblazer"},{"v.VaultbornTyrant","Vaultborn Tyrant"}})run("Mandatory token draw chain drains through Kodama with "+engine[1],()->{Chain c=new Chain(engine[0],engine[1]);c.progress();check(!c.prompt(),"Known mandatory draw progress accepted loop draw");drain(c.f,200);check(c.f.game.getStack().isEmpty()&&!c.f.game.hasEnded(),"Mandatory chain did not drain without a draw outcome");check(c.f.bot.getLibrary().size()<c.initial,"Mandatory draws were suppressed");});
  run("Natural Trailblazer and Vaultborn chain survives actual loop detector",()->{final int[] refusals={0};org.apache.log4j.Logger log=org.apache.log4j.Logger.getLogger(ComputerPlayerFourthSeat.class);log.setLevel(org.apache.log4j.Level.DEBUG);org.apache.log4j.AppenderSkeleton capture=new org.apache.log4j.AppenderSkeleton(){protected void append(org.apache.log4j.spi.LoggingEvent e){if(String.valueOf(e.getRenderedMessage()).contains("BOUNDED_FINITE_PROGRESS_REFUSAL"))refusals[0]++;}public void close(){}public boolean requiresLayout(){return false;}};log.addAppender(capture);try{Chain c=new Chain("o.OutcasterTrailblazer","Outcaster Trailblazer");c.f.board("v.VaultbornTyrant","Vaultborn Tyrant");int steps=0;while(!c.f.game.getStack().isEmpty()&&steps++<200){resolve(c.f);check(!c.f.game.hasEnded(),"Finite mandatory chain became engine draw");}check(c.f.game.getStack().isEmpty(),"Mandatory chain failed bounded drain");check(c.f.bot.getLibrary().size()<c.initial,"No actual mandatory draws");check(refusals[0]==1,"Actual loop detector did not exercise one bounded refusal");}finally{log.removeAppender(capture);}});
  run("Known progress permits one refusal and optional drain only",()->{Chain c=new Chain();c.progress();check(!c.prompt(),"Known finite progress accepted draw");check(c.prompt(),"Second unresolved prompt repeatedly refused");drain(c.f,100);check(!c.f.game.hasEnded(),"Manual optional drain ended game");});
  run("No-progress and unknown protocol preserve confirmation",()->{Chain c=new Chain();check(c.prompt(),"No-progress draw protocol incorrectly refused");check(c.f.bot.chooseUse(Outcome.Detriment,"An unrelated choice",null,c.f.game),"Unrelated choice hijacked");});
  run("Empty stack resets finite chain recovery",()->{Chain c=new Chain();c.progress();check(!c.prompt(),"No first refusal");drain(c.f,100);check(c.prompt(),"Empty stack reused stale refusal");});
  run("Own pending work holds proactive flash body then resolves and casts",()->{FourthSeatRealGameTest.Fixture f=fixture("g.GoreclawTerrorOfQalSisma","Goreclaw, Terror of Qal Sisma");f.board("y.YevaNaturesHerald","Yeva, Nature's Herald");Card draw=f.hand("h.Harmonize","Harmonize"),body=f.hand("g.GrizzlyBears","Grizzly Bears");for(int k=0;k<8;k++)f.bot.getLibrary().putOnTop(f.card("a.ApexAltisaur","Apex Altisaur"),f.game);f.bot.getManaPool().addMana(Mana.GreenMana(6),f.game,body.getSpellAbility());check(f.bot.activateAbility(draw.getSpellAbility(),f.game),"Own pending spell failed");check(!f.bot.priority(f.game),"Proactive flash added before own work resolved");check(f.bot.getHand().contains(body.getId()),"Flash body cast while own work pending");resolve(f);cast(f,body,2);});
  run("Own pending work still permits actual reactive protection",()->{FourthSeatRealGameTest.Fixture f=new FourthSeatRealGameTest.Fixture();f.game.initializeRollbackOrder();Permanent a=f.board("a.AesiTyrantOfGyreStrait","Aesi, Tyrant of Gyre Strait");f.identifyCommander(a.getId());Card own=f.hand("g.GrowthSpiral","Growth Spiral"),protect=f.hand("h.HeroicIntervention","Heroic Intervention");library(f,8);f.mana(protect);check(f.bot.activateAbility(own.getSpellAbility(),f.game),"Own pending spell failed");Card murder=f.enemyHand("m.Murder","Murder");murder.getSpellAbility().getTargets().get(0).addTarget(a.getId(),murder.getSpellAbility(),f.game);f.castEnemy(murder);cast(f,protect,1);drain(f,20);check(f.game.getPermanent(a.getId())!=null,"Own stack guard denied protection");});
  for(boolean monarch:new boolean[]{false,true})for(boolean territory:new boolean[]{false,true})run("Regal triggered color actual path monarch="+monarch+" territory="+territory,()->{FourthSeatRealGameTest.Fixture f=fixture("g.GishathSunsAvatar","Gishath, Sun's Avatar");f.board("r.RegalBehemoth","Regal Behemoth");if(monarch)f.game.getState().setMonarchId(f.bot.getId());Permanent land=f.board(territory?"u.UnclaimedTerritory":"basiclands.Forest",territory?"Unclaimed Territory":"Forest");if(territory)f.game.getState().setValue(land.getId()+"_type",SubType.DINOSAUR);Permanent enemy=f.enemyBoard(0,"l.LyraDawnbringer","Lyra Dawnbringer");Card path=f.hand("p.PathToExile","Path to Exile");if(!monarch)reject(f,path);else{check(f.bot.priority(f.game),"Triggered feeder absent");check(f.game.getState().getZone(path.getId())==Zone.HAND&&f.bot.getManaPool().getMana().getWhite()==1,"Bonus W not actually produced before cast");cast(f,path,2);drain(f,10);check(f.game.getPermanent(enemy.getId())==null,"Path did not resolve");}});
  for(boolean extra:new boolean[]{false,true})run("Lair X demand preserves conversion input extraForest="+extra,()->{FourthSeatRealGameTest.Fixture f=fixture("g.GhaltaPrimalHunger","Ghalta, Primal Hunger");f.game.getCard(f.bot.getCommandersIds().iterator().next()).moveToZone(Zone.EXILED,null,f.game,false);Permanent lair=f.board("l.LairOfTheHydra","Lair of the Hydra");f.board("n.NykthosShrineToNyx","Nykthos, Shrine to Nyx");f.board("g.Gigantosaurus","Gigantosaurus");if(extra)f.board("basiclands.Forest","Forest");f.bot.getManaPool().addMana(Mana.ColorlessMana(2),f.game,lair.getAbilities().get(0));FourthSeatRealGameTest.Trace t=new FourthSeatRealGameTest.Trace();org.apache.log4j.Logger log=org.apache.log4j.Logger.getLogger(ComputerPlayerFourthSeat.class);log.addAppender(t);try{for(int i=0;i<5&&f.game.getStack().isEmpty();i++)check(f.bot.priority(f.game),"Lair action unexpectedly passed");check(t.failures==0&&!f.game.getStack().isEmpty(),"Lair failed after X selection");resolve(f);check(f.game.getPermanent(lair.getId()).isCreature(f.game)&&f.game.getPermanent(lair.getId()).getPower().getValue()>=1,"Lair animation absent");}finally{log.removeAppender(t);}});
  for(boolean empty:new boolean[]{false,true})run("Produced Regal bonus survives loss but stale capacity does not empty="+empty,()->{FourthSeatRealGameTest.Fixture f=fixture("g.GishathSunsAvatar","Gishath, Sun's Avatar");Permanent regal=f.board("r.RegalBehemoth","Regal Behemoth");f.game.getState().setMonarchId(f.bot.getId());Permanent land=f.board("basiclands.Forest","Forest");f.enemyBoard(0,"l.LyraDawnbringer","Lyra Dawnbringer");Card c=f.hand("p.PathToExile","Path to Exile");check(f.bot.priority(f.game),"Real bonus feeder absent");check(f.bot.getManaPool().getMana().getWhite()==1&&f.game.getState().getZone(c.getId())==Zone.HAND,"Bonus mana not produced separately");f.game.getState().setMonarchId(f.foes[0].getId());regal.moveToZone(Zone.GRAVEYARD,null,f.game,false);if(empty){f.bot.getManaPool().emptyPool(f.game);land.setTapped(false);check(!fund(f,c.getSpellAbility()),"Removed bonus still funded white");reject(f,c);}else cast(f,c,1);});
  run("Finite drain ownership and mandatory draw remain engine controlled",()->{Chain c=new Chain();c.progress();check(!c.prompt(),"First finite refusal absent");Ability own=c.kodama.getAbilities(c.f.game).stream().filter(a->a.getEffects().stream().anyMatch(e->e.getOutcome()==Outcome.Benefit)).findFirst().orElse(c.kodama.getAbilities().get(0)).copy();own.setControllerId(c.f.bot.getId());own.setSourceId(c.kodama.getId());check(!c.f.bot.chooseUse(Outcome.Benefit,"Optional own Kodama",own,c.f.game),"Draining own optional put not declined");Ability enemy=own.copy();enemy.setControllerId(c.f.foes[0].getId());check(c.f.bot.chooseUse(Outcome.Benefit,"Other controller choice",enemy,c.f.game),"Foreign optional ability hijacked");int before=c.f.bot.getLibrary().size();c.f.bot.drawCards(1,own,c.f.game);check(c.f.bot.getLibrary().size()==before-1,"Mandatory draw silently skipped while draining");});
  run("World War Hulk pays3GG through two real monarch land bonuses",()->{Hulk h=new Hulk(true,true,true);FourthSeatRealGameTest.Trace t=new FourthSeatRealGameTest.Trace();org.apache.log4j.Logger log=org.apache.log4j.Logger.getLogger(ComputerPlayerFourthSeat.class);log.addAppender(t);try{h.first();check(h.f.bot.priority(h.f.game),"Second triggered feeder absent");if(h.f.game.getState().getZone(h.spell.getId())==Zone.HAND){check(h.f.bot.getManaPool().getMana().count()==4&&h.f.bot.getManaPool().getMana().getGreen()>=2,"Second separate feeder output wrong");check(!h.f.game.getPermanent(h.signet.getId()).isTapped(),"Separate second land feeder spent Signet too");cast(h.f,h.spell,1);}check(h.f.game.getState().getZone(h.spell.getId())==Zone.STACK&&h.f.game.getPermanent(h.territory.getId()).isTapped()&&h.f.game.getPermanent(h.retreat.getId()).isTapped(),"Actual cast failed to consume both distinct land sources");check(h.f.bot.getManaPool().getMana().count()==0&&h.f.game.getPermanent(h.signet.getId()).isTapped(),"World War Hulk exact3GG payment wrong");drain(h.f,10);check(h.f.game.getPermanent(h.spell.getId())!=null,"Paid Saga failed actual resolution");check(t.failures==0&&h.f.game.rollbackCount==0,"Two-bonus sequence concealed failed activation");}finally{log.removeAppender(t);}});
  for(String missing:new String[]{"monarch","territory","retreat"})run("Two-bonus Hulk rejects missing "+missing,()->{Hulk h=new Hulk(!missing.equals("monarch"),!missing.equals("territory"),!missing.equals("retreat"));check(!fund(h.f,h.spell.getSpellAbility()),"Missing triggered source falsely funds five");reject(h.f,h.spell);check(h.f.bot.getManaPool().getMana().count()==0,"Unavailable plan tapped speculative source");});
  for(String loss:new String[]{"monarch","remaining-land","regal"})run("Two-bonus Hulk replans after first real action loses "+loss,()->{Hulk h=new Hulk(true,true,true);h.first();int actualPool=h.f.bot.getManaPool().getMana().count();if(loss.equals("monarch"))h.f.game.getState().setMonarchId(h.f.foes[0].getId());if(loss.equals("remaining-land")){Permanent remaining=h.f.game.getPermanent(h.territory.getId()).isTapped()?h.retreat:h.territory;remaining.moveToZone(Zone.GRAVEYARD,null,h.f.game,false);}if(loss.equals("regal"))h.regal.moveToZone(Zone.GRAVEYARD,null,h.f.game,false);h.f.game.applyEffects();check(!fund(h.f,h.spell.getSpellAbility()),"Stale multi-trigger certificate survived lost capacity");reject(h.f,h.spell);check(h.f.bot.getManaPool().getMana().count()==actualPool&&h.f.bot.getManaPool().getMana().getGreen()>=1,"Already produced bonus was erased or speculative funding spent");});
  finish("RECOVERED_PROTOCOL");
 }

 static final class Hulk {
  final FourthSeatRealGameTest.Fixture f;final Permanent regal,territory,retreat,signet;final Card spell;
  Hulk(boolean monarch,boolean territoryAvailable,boolean retreatAvailable)throws Exception{f=fixture("g.GishathSunsAvatar","Gishath, Sun's Avatar");regal=f.board("r.RegalBehemoth","Regal Behemoth");if(monarch)f.game.getState().setMonarchId(f.bot.getId());territory=f.board("u.UnclaimedTerritory","Unclaimed Territory");f.game.getState().setValue(territory.getId()+"_type",SubType.DINOSAUR);retreat=f.board("c.ClifftopRetreat","Clifftop Retreat");signet=f.board("a.ArcaneSignet","Arcane Signet");territory.setTapped(!territoryAvailable);retreat.setTapped(!retreatAvailable);spell=f.hand("w.WorldWarHulk","World War Hulk");f.game.applyEffects();}
  void first(){check(f.bot.priority(f.game),"First real triggered feeder absent");check(f.game.getState().getZone(spell.getId())==Zone.HAND&&f.game.getStack().isEmpty(),"First funding callback must not cast outer Saga");check(f.bot.getManaPool().getMana().count()==2&&f.bot.getManaPool().getMana().getGreen()>=1,"First actual land/bonus output wrong");check(f.game.getPermanent(territory.getId()).isTapped()!=f.game.getPermanent(retreat.getId()).isTapped(),"First callback did not consume exactly one land");f.game.checkStateAndTriggered();}
 }
}
